var QUIZ_LOTTOD=[
["ecg-tossici","In un'intossicazione da antidepressivi triciclici, quale reperto ECG è risultato il miglior predittore indipendente di convulsioni e aritmie?",["Onda T alta e appuntita in V2-V4","Onda R terminale in aVR di almeno 3 mm","Intervallo PR superiore a 200 ms","Onda U prominente in V2-V3"],1,"Nello studio di Liebelt (1995) una R terminale in aVR ≥ 3 mm è stata l'unica variabile ECG a predire in modo significativo convulsioni e aritmie."],
["ecg-tossici","Paziente con sospetta ingestione di triciclici: QRS 130 ms e tachicardia. Che cosa si prepara su prescrizione?",["Flecainide endovena","Potassio cloruro in bolo","Verapamil endovena","Bicarbonato di sodio endovena"],3,"Il bicarbonato di sodio, con il carico di sodio e l'alcalinizzazione, riduce il blocco dei canali del sodio; gli antiaritmici di classe IC lo peggiorano."],
["ecg-tossici","Quale quadro ECG è più tipico di un sovradosaggio di verapamil o di un beta-bloccante?",["Bradicardia con blocco AV e ipotensione","Tachicardia sinusale con QRS largo","Onde delta con PR corto","Sopraslivellamento ST a sella"],0,"Calcio-antagonisti non diidropiridinici e beta-bloccanti deprimono il nodo del seno e il nodo AV: bradicardia, blocchi AV e ipotensione."],
["ecg-tossici","Un giovane con agitazione, midriasi, ipertermia e dolore toracico dopo uso di cocaina: che cosa va tenuto presente?",["La cocaina dà solo bradicardia","L'ECG non serve nei pazienti giovani","Lo spasmo coronarico può causare un infarto anche senza malattia coronarica","I beta-bloccanti sono il primo trattamento dell'agitazione"],2,"La cocaina causa tachicardia, ipertensione e spasmo coronarico con possibile infarto anche nel giovane; serve sempre l'ECG a 12 derivazioni."],
["ecg-sede-infarto","Sopraslivellamento ST in D2, D3 e aVF con sottoslivellamento in aVL. Quale derivazione aggiuntiva va registrata?",["V7","aVR ripetuta","V4R","V1 spostata in alto"],2,"Nell'infarto inferiore, spesso da coronaria destra, si cercano le derivazioni destre (V4R) per il coinvolgimento del ventricolo destro."],
["ecg-sede-infarto","Dolore toracico con sottoslivellamento ST in V1-V3, R alta in V2 e T positive. Che cosa si sospetta?",["Infarto della parete posteriore","Pericardite","Effetto digitalico","Blocco di branca destra isolato"],0,"È l'immagine speculare di un infarto posteriore: si registrano V7-V9, dove un sopraslivellamento ≥ 0,5 mm conferma."],
["ecg-sede-infarto","Secondo la Quarta definizione universale, quale sopraslivellamento in V2-V3 è significativo in una donna?",["≥ 0,5 mm","≥ 3 mm","≥ 2,5 mm","≥ 1,5 mm"],3,"In V2-V3 la soglia è ≥ 1,5 mm nelle donne, ≥ 2 mm negli uomini dai 40 anni e ≥ 2,5 mm sotto i 40."],
["ecg-sede-infarto","Qual è in genere il primo segno ECG dopo l'occlusione di una coronaria?",["Onda Q profonda","Onda T iperacuta","Onda T invertita","Onda U"],1,"Nei primi minuti compaiono T alte, larghe e simmetriche; seguono il sopraslivellamento ST, poi le onde Q e l'inversione delle T."]
];
